{
  "incident_id": "mitre-T1041",
  "telemetry_version": 1,
  "assessment": "Confirmed active exfiltration from critical host web-01 to c2-01. Immediate containment of the egress channel is required to stop data loss while preserving management and evidence collection channels.",
  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "Evidence M1 confirms unauthorized sensitive data is actively leaving web-01 to c2-01. This is a confirmed threat requiring immediate containment to prevent further exfiltration."
    }
  ],
  "actions": [
    {
      "kind": "block_egress",
      "target_id": "c2-01",
      "scope_host_ids": [
        "web-01"
      ],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Blocks the confirmed exfiltration path from the critical host web-01 to the C2 destination c2-01. This interrupts the attacker's ability to exfiltrate data. Management and evidence_collector channels are preserved to maintain visibility and control.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact on web-01 is unknown as dependency details are not provided, though targeted egress blocking is less disruptive than full isolation."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

